-- Project texts, full length, English and Bangla:
--   * the five open research models (in every version), and
--   * the Researcher copies of the engineering projects (from part 3).
-- Run in the Supabase SQL editor. Safe to re-run.
--
-- Each gets a 2-3 paragraph description, 4-5 detailed points, its tech stack,
-- a Bangla title and consistent dates. Only rows nobody has edited are touched
-- (updated_at = created_at); the Developer rows stay exactly as they are.
-- Facts are from the CVs, the papers and the Hugging Face model cards.
-- Generated by a script; edit the texts in batools afterwards.

BEGIN;

UPDATE pf_projects p SET
  title_bn = v.title_bn,
  duration_en = v.duration_en, duration_bn = v.duration_bn,
  tech_stack = v.tech,
  description_en = v.desc_en, description_bn = v.desc_bn,
  responsibilities_en = v.bul_en, responsibilities_bn = v.bul_bn,
  updated_at = p.created_at          -- still counts as untouched, so a re-run refreshes it
FROM (VALUES
  ($q$all$q$, $q$Bangla Fake News Detection$q$, $q$বাংলা ভুয়া খবর শনাক্তকরণ (বাংলা BERT)$q$, $q$Open research model · 2026$q$, $q$উন্মুক্ত গবেষণা মডেল · ২০২৬$q$, ARRAY[$q$Python$q$, $q$PyTorch$q$, $q$Transformers$q$, $q$Bangla BERT$q$, $q$TF-IDF$q$, $q$scikit-learn$q$, $q$LIME$q$, $q$ONNX$q$]::text[], $q$<p>Fake and manipulated news spreads quickly on Bangla social media, yet Bengali has few annotated datasets and few models built for it. This project, from the <em>International Journal of Advanced Computer Research</em> (2026) paper, fine-tunes a <strong>Bangla BERT</strong> that scores a Bangla news article as fake or authentic.</p><p>Trained on BanFakeNews (1,299 fake and 3,900 authentic articles, a 1:3 ratio) and compared with TF-IDF baselines (Logistic Regression, Decision Tree, Random Forest, Gradient Boosting), it reaches <strong>94.49% accuracy, 90.28% recall on fake news and 98.36% ROC-AUC</strong>, catching far more fakes than the classical models. The model is open on Hugging Face with an in-browser demo.</p>$q$, $q$<p>বাংলা সোশ্যাল মিডিয়ায় ভুয়া ও বিকৃত খবর দ্রুত ছড়ায়, অথচ বাংলায় চিহ্নিত ডেটাসেট ও ভাষা-নির্দিষ্ট মডেল খুবই কম। <em>International Journal of Advanced Computer Research</em> (২০২৬) পেপারের এই প্রকল্পে একটি <strong>বাংলা BERT</strong> ফাইন-টিউন করা হয়েছে, যা কোনো বাংলা সংবাদকে ভুয়া বা সত্য হিসেবে স্কোর করে।</p><p>BanFakeNews-এ (১,২৯৯টি ভুয়া ও ৩,৯০০টি সত্য সংবাদ, ১:৩ অনুপাত) প্রশিক্ষিত এবং TF-IDF বেসলাইনের (লজিস্টিক রিগ্রেশন, ডিসিশন ট্রি, র‍্যান্ডম ফরেস্ট, গ্রেডিয়েন্ট বুস্টিং) সাথে তুলনায় এটি <strong>৯৪.৪৯% accuracy, ভুয়া খবরে ৯০.২৮% recall ও ৯৮.৩৬% ROC-AUC</strong> পায়, ক্লাসিক্যাল মডেলের চেয়ে অনেক বেশি ভুয়া ধরে। মডেলটি ব্রাউজার ডেমোসহ Hugging Face-এ উন্মুক্ত।</p>$q$, ARRAY[$q$Prepared Bangla text (cleaning, stop words, numbers) with TF-IDF features for classical models and WordPiece tokens for BERT.$q$, $q$Compared four classical classifiers under 5-fold cross-validation with class-weight handling for the 1:3 imbalance.$q$, $q$Fine-tuned Bangla BERT (AdamW, learning rate 2e-5, batch 8, 3 epochs): 94.49% accuracy, 89.03% F1, 90.28% recall, 98.36% ROC-AUC.$q$, $q$Measured training cost (0.37 s for Logistic Regression vs about 14 minutes for BERT) and explained predictions with LIME.$q$, $q$Exported an 8-bit ONNX copy (658 MB → 165 MB) so the demo runs entirely in the visitor's browser.$q$]::text[], ARRAY[$q$ক্লাসিক্যাল মডেলের জন্য TF-IDF ফিচার ও BERT-এর জন্য WordPiece টোকেনসহ বাংলা টেক্সট প্রস্তুত (পরিষ্কার, স্টপ ওয়ার্ড, সংখ্যা)।$q$, $q$১:৩ ভারসাম্যহীনতার জন্য শ্রেণি-ওজনসহ ৫-ফোল্ড ক্রস-ভ্যালিডেশনে চারটি ক্লাসিক্যাল ক্লাসিফায়ারের তুলনা।$q$, $q$বাংলা BERT ফাইন-টিউন (AdamW, লার্নিং রেট 2e-5, ব্যাচ ৮, ৩ ইপক): ৯৪.৪৯% accuracy, ৮৯.০৩% F1, ৯০.২৮% recall, ৯৮.৩৬% ROC-AUC।$q$, $q$প্রশিক্ষণ খরচ পরিমাপ (লজিস্টিক রিগ্রেশন ০.৩৭ সেকেন্ড, BERT প্রায় ১৪ মিনিট) এবং LIME দিয়ে পূর্বাভাসের ব্যাখ্যা।$q$, $q$৮-বিট ONNX কপি (৬৫৮ MB → ১৬৫ MB) তৈরি, যাতে ডেমো সম্পূর্ণ দর্শকের ব্রাউজারে চলে।$q$]::text[]),
  ($q$all$q$, $q$Bangladesh Monthly Weather Forecasting$q$, $q$বাংলাদেশের মাসিক আবহাওয়া পূর্বাভাস$q$, $q$Open research model · 2026$q$, $q$উন্মুক্ত গবেষণা মডেল · ২০২৬$q$, ARRAY[$q$Python$q$, $q$scikit-learn$q$, $q$XGBoost$q$, $q$SVR$q$, $q$LSTM$q$, $q$GRU$q$, $q$SARIMA$q$, $q$SHAP$q$, $q$Conformal Prediction$q$]::text[], $q$<p>One-month-ahead forecasts of rainfall, temperature and humidity for <strong>24 Bangladesh Meteorological Department stations</strong>, built on a quality-controlled panel from 1981 to 2022. Many published ML forecasts are inflated by data leakage; this project uses a strictly <strong>leakage-controlled protocol</strong>: every predictor is observed before the forecast month, models are tuned by nested rolling-origin validation on 1982–2017, and re-fitted each year over 2018–2022.</p><p>Machine learning beats the station climatology for every target (temperature RMSE <strong>0.74 °C</strong>, humidity 4.35%), a per-station SARIMA proves a strong baseline, and <strong>conformal prediction intervals</strong> give honest 90% ranges. The models, the data (Kaggle) and the full code (GitHub) are public, with a live demo.</p>$q$, $q$<p><strong>বাংলাদেশ আবহাওয়া অধিদপ্তরের ২৪টি স্টেশনে</strong> ১৯৮১–২০২২ সালের মান-নিয়ন্ত্রিত প্যানেলের ওপর বৃষ্টিপাত, তাপমাত্রা ও আর্দ্রতার এক মাস আগের পূর্বাভাস। অনেক প্রকাশিত পূর্বাভাস ডেটা লিকেজে অতিরঞ্জিত; এই প্রকল্প কঠোর <strong>লিকেজ-নিয়ন্ত্রিত প্রটোকল</strong> মানে: প্রতিটি প্রেডিক্টর পূর্বাভাসের মাসের আগে পর্যবেক্ষিত, ১৯৮২–২০১৭ সালে নেস্টেড রোলিং-অরিজিন যাচাইয়ে টিউনিং, এবং ২০১৮–২০২২ সালে প্রতি বছর পুনঃপ্রশিক্ষণ।</p><p>প্রতিটি লক্ষ্যে মেশিন লার্নিং স্টেশনের জলবায়ুগত গড়ের চেয়ে ভালো (তাপমাত্রা RMSE <strong>০.৭৪ °C</strong>, আর্দ্রতা ৪.৩৫%), স্টেশনভিত্তিক SARIMA শক্তিশালী বেসলাইন, আর <strong>কনফরমাল প্রেডিকশন ইন্টারভাল</strong> সৎ ৯০% পরিসর দেয়। মডেল, ডেটা (Kaggle) ও পূর্ণ কোড (GitHub) উন্মুক্ত, লাইভ ডেমোসহ।</p>$q$, ARRAY[$q$Built the quality-controlled 24-station panel: range, outlier and consistency checks, removal of zero-coded missing values, conservative imputation of predictors only.$q$, $q$Designed leakage-free features: target lags and seasonal means, last month's other variables, neighbouring stations and station climatology.$q$, $q$Compared nine ML / deep-learning models (Ridge, trees, SVR, KNN, XGBoost, MLP, LSTM, GRU) against climatology, persistence, seasonal naive and SARIMA.$q$, $q$Verified with skill scores, Diebold-Mariano tests, seasonal, extreme-event and leave-one-division-out results, and SHAP explanations.$q$, $q$Added season-stratified conformal intervals (0.89–0.97 coverage) and released two model versions (trained to 2017 and to 2022).$q$]::text[], ARRAY[$q$মান-নিয়ন্ত্রিত ২৪ স্টেশনের প্যানেল তৈরি: পরিসর, আউটলায়ার ও সামঞ্জস্য যাচাই, শূন্য-চিহ্নিত অনুপস্থিত মান বাদ, শুধু প্রেডিক্টরে সংযত ইমপুটেশন।$q$, $q$লিকেজ-মুক্ত ফিচার নকশা: লক্ষ্যের পূর্ববর্তী মান ও ঋতুগড়, আগের মাসের অন্যান্য ভেরিয়েবল, পার্শ্ববর্তী স্টেশন ও স্টেশনের জলবায়ুগত গড়।$q$, $q$জলবায়ুগত গড়, পারসিস্টেন্স, সিজনাল নাইভ ও SARIMA-র বিপরীতে নয়টি মডেলের (Ridge, ট্রি, SVR, KNN, XGBoost, MLP, LSTM, GRU) তুলনা।$q$, $q$স্কিল স্কোর, Diebold-Mariano টেস্ট, ঋতু, চরম ঘটনা ও leave-one-division-out ফলাফল এবং SHAP ব্যাখ্যা দিয়ে যাচাই।$q$, $q$ঋতুভিত্তিক কনফরমাল ইন্টারভাল (০.৮৯–০.৯৭ কভারেজ) যোগ এবং দুটি মডেল সংস্করণ প্রকাশ (২০১৭ ও ২০২২ পর্যন্ত প্রশিক্ষিত)।$q$]::text[]),
  ($q$all$q$, $q$Maternal & Fetal Health Risk Prediction$q$, $q$মাতৃ ও ভ্রূণের স্বাস্থ্যঝুঁকি পূর্বাভাস$q$, $q$Open research model · 2026$q$, $q$উন্মুক্ত গবেষণা মডেল · ২০২৬$q$, ARRAY[$q$Python$q$, $q$scikit-learn$q$, $q$Random Forest$q$, $q$Decision Tree$q$, $q$MLP$q$, $q$Pandas$q$, $q$Sensitivity Analysis$q$]::text[], $q$<p>Pregnancy complications are often recognised late in Bangladesh. This project, from the <em>Cloud Computing and Data Science</em> (2026) paper, predicts whether a pregnancy is <strong>low, mid or high risk</strong> from 19 routine clinical measurements collected at hospitals in Noakhali, and ranks which measurements matter most.</p><p>Seven classifiers were compared and a sensitivity analysis points to <strong>blood pressure, fetal movement, fetal heart rate and amniotic fluid</strong> as the strongest risk drivers. A later re-check found the 930 rows held only 100 unique patients, so the released models are evaluated honestly on unique patients: the random forest reaches <strong>75.6% accuracy</strong> under repeated cross-validation. Research use only, with a live demo.</p>$q$, $q$<p>বাংলাদেশে গর্ভকালীন জটিলতা প্রায়ই দেরিতে ধরা পড়ে। <em>Cloud Computing and Data Science</em> (২০২৬) পেপারের এই প্রকল্প নোয়াখালীর হাসপাতাল থেকে সংগৃহীত ১৯টি নিয়মিত ক্লিনিক্যাল পরিমাপ থেকে গর্ভাবস্থা <strong>নিম্ন, মাঝারি বা উচ্চ ঝুঁকির</strong> কিনা পূর্বাভাস দেয় এবং কোন পরিমাপ বেশি গুরুত্বপূর্ণ তা র‍্যাঙ্ক করে।</p><p>সাতটি ক্লাসিফায়ারের তুলনা ও সংবেদনশীলতা বিশ্লেষণে <strong>রক্তচাপ, ভ্রূণের নড়াচড়া, ভ্রূণের হৃদস্পন্দন ও অ্যামনিওটিক তরল</strong> সবচেয়ে বড় ঝুঁকির চালক। পরে দেখা যায় ৯৩০টি সারিতে অনন্য রোগী মাত্র ১০০ জন, তাই প্রকাশিত মডেল অনন্য রোগীদের ওপর সৎভাবে মূল্যায়িত: পুনরাবৃত্ত ক্রস-ভ্যালিডেশনে র‍্যান্ডম ফরেস্ট <strong>৭৫.৬% accuracy</strong>। শুধু গবেষণার জন্য, লাইভ ডেমোসহ।</p>$q$, ARRAY[$q$Prepared the hospital records: cleaning, imputation of missing values, encoding, feature selection and scaling.$q$, $q$Compared seven classifiers (Multinomial Logistic Regression, Naïve Bayes, KNN, SVM, Decision Tree, Random Forest, MLP) under one protocol.$q$, $q$Ranked the 19 inputs with a mean-based sensitivity analysis to support a priority-based antenatal monitoring checklist.$q$, $q$Found repeated patient records across the train/test split and re-evaluated on the 100 unique patients with 20× repeated 5-fold cross-validation.$q$, $q$Released a random forest (75.6% accuracy, 74.3% macro F1) and an explainable depth-3 decision tree with an interactive demo.$q$]::text[], ARRAY[$q$হাসপাতালের রেকর্ড প্রস্তুত: পরিষ্কার, অনুপস্থিত মান পূরণ, এনকোডিং, ফিচার নির্বাচন ও স্কেলিং।$q$, $q$একটি প্রটোকলে সাতটি ক্লাসিফায়ারের তুলনা (মাল্টিনোমিয়াল লজিস্টিক রিগ্রেশন, নাইভ বেইজ, KNN, SVM, ডিসিশন ট্রি, র‍্যান্ডম ফরেস্ট, MLP)।$q$, $q$গড়-ভিত্তিক সংবেদনশীলতা বিশ্লেষণে ১৯টি ইনপুট র‍্যাঙ্ক, অগ্রাধিকারভিত্তিক প্রসবপূর্ব পর্যবেক্ষণ চেকলিস্টের জন্য।$q$, $q$ট্রেন/টেস্ট বিভাজনে রোগীর পুনরাবৃত্ত রেকর্ড খুঁজে পেয়ে ১০০ জন অনন্য রোগীর ওপর ২০ বার পুনরাবৃত্ত ৫-ফোল্ড ক্রস-ভ্যালিডেশনে পুনর্মূল্যায়ন।$q$, $q$ইন্টারঅ্যাকটিভ ডেমোসহ র‍্যান্ডম ফরেস্ট (৭৫.৬% accuracy, ৭৪.৩% macro F1) ও ব্যাখ্যাযোগ্য ৩-গভীরতার ডিসিশন ট্রি প্রকাশ।$q$]::text[]),
  ($q$all$q$, $q$Bangla Cyberbullying Detection$q$, $q$বাংলা সাইবার বুলিং শনাক্তকরণ$q$, $q$Open research model · 2026$q$, $q$উন্মুক্ত গবেষণা মডেল · ২০২৬$q$, ARRAY[$q$Python$q$, $q$scikit-learn$q$, $q$TF-IDF$q$, $q$Logistic Regression$q$, $q$NLP$q$, $q$Code-mixed text$q$]::text[], $q$<p>Bangla social media mixes Bangla script, Romanized Bangla and English, with countless spellings of the same word, which defeats most bullying detectors. This project builds a <strong>two-stage classifier</strong>: it first predicts one of 9 sentiment classes, then decides bullying, non-bullying or neutral from the text together with those sentiment probabilities.</p><p>It comes with a <strong>3,150-comment dataset</strong> from Bangladeshi YouTube and Facebook pages, labelled by three annotators. Results are reported honestly (56.3% accuracy, macro F1 0.49 against 0.24 for a majority baseline), with the human-label upper bound showing how much better sentiment prediction must become. Research use only, with a live demo.</p>$q$, $q$<p>বাংলা সোশ্যাল মিডিয়ায় বাংলা লিপি, রোমান হরফের বাংলা ও ইংরেজি মিশে থাকে, একই শব্দের অসংখ্য বানানসহ, যা বেশিরভাগ বুলিং শনাক্তকারীকে ব্যর্থ করে। এই প্রকল্প একটি <strong>দুই ধাপের ক্লাসিফায়ার</strong> তৈরি করে: প্রথমে ৯টি অনুভূতি-শ্রেণির একটি পূর্বাভাস, তারপর টেক্সট ও সেই সম্ভাবনা মিলিয়ে বুলিং, নন-বুলিং বা নিরপেক্ষ নির্ধারণ।</p><p>সাথে আছে বাংলাদেশি YouTube ও Facebook পেজের <strong>৩,১৫০টি মন্তব্যের ডেটাসেট</strong>, তিনজন চিহ্নিতকারীর লেবেলসহ। ফলাফল সৎভাবে উপস্থাপিত (৫৬.৩% accuracy, macro F1 ০.৪৯, যেখানে সংখ্যাগরিষ্ঠ বেসলাইন ০.২৪), আর মানুষের লেবেলের ঊর্ধ্বসীমা দেখায় অনুভূতি-পূর্বাভাস কতটা ভালো হতে হবে। শুধু গবেষণার জন্য, লাইভ ডেমোসহ।</p>$q$, ARRAY[$q$Co-built the dataset: 2,118 YouTube and 1,031 Facebook comments, three annotators, labels merged by fixed priority rules.$q$, $q$Combined word n-grams with character 2–4-grams so that varied Romanized spellings still share features.$q$, $q$Trained stage 2 on out-of-fold stage-1 predictions, so it behaves the same on new comments as in evaluation.$q$, $q$Evaluated with 3× repeated 5-fold cross-validation, keeping identical comments in the same fold.$q$, $q$Published the model and an in-browser demo with clear limits: not a moderation tool.$q$]::text[], ARRAY[$q$ডেটাসেট সহ-নির্মাণ: ২,১১৮টি YouTube ও ১,০৩১টি Facebook মন্তব্য, তিনজন চিহ্নিতকারী, নির্দিষ্ট অগ্রাধিকার নিয়মে লেবেল একত্রীকরণ।$q$, $q$শব্দের n-গ্রামের সাথে অক্ষরের ২–৪-গ্রাম যুক্ত, যাতে রোমান হরফের ভিন্ন বানানও ফিচার ভাগ করে।$q$, $q$দ্বিতীয় ধাপ প্রথম ধাপের আউট-অফ-ফোল্ড পূর্বাভাসে প্রশিক্ষিত, তাই নতুন মন্তব্যে মূল্যায়নের মতোই আচরণ করে।$q$, $q$৩ বার পুনরাবৃত্ত ৫-ফোল্ড ক্রস-ভ্যালিডেশনে মূল্যায়ন, একই মন্তব্য একই ফোল্ডে রেখে।$q$, $q$স্পষ্ট সীমাসহ মডেল ও ব্রাউজার ডেমো প্রকাশ: মডারেশন টুল নয়।$q$]::text[]),
  ($q$all$q$, $q$Movie Review Sentiment Analysis$q$, $q$সিনেমা রিভিউয়ের অনুভূতি বিশ্লেষণ (MPNet)$q$, $q$Open research model · 2026$q$, $q$উন্মুক্ত গবেষণা মডেল · ২০২৬$q$, ARRAY[$q$Python$q$, $q$Sentence Transformers$q$, $q$MPNet$q$, $q$scikit-learn$q$, $q$Logistic Regression$q$, $q$ONNX$q$]::text[], $q$<p>A comparative study of how to represent movie reviews for sentiment classification: <strong>bag-of-words, TF-IDF and sentence embeddings</strong> across logistic regression, SVM, naive Bayes, random forest, KNN and a neural network, on the IMDB 50K reviews.</p><p>Sentence embeddings from <strong>all-mpnet-base-v2</strong> with a logistic regression gave the best lightweight model: <strong>91.11% accuracy and 96.94% ROC-AUC</strong>, measured after removing 419 duplicate reviews so no test review also appears in training. A 16-bit copy runs fully in the browser demo, and the embedded dataset is on Kaggle.</p>$q$, $q$<p>সিনেমা রিভিউকে অনুভূতি শ্রেণিকরণের জন্য কীভাবে উপস্থাপন করা যায় তার তুলনামূলক গবেষণা: IMDB 50K রিভিউয়ে লজিস্টিক রিগ্রেশন, SVM, নাইভ বেইজ, র‍্যান্ডম ফরেস্ট, KNN ও নিউরাল নেটওয়ার্কে <strong>bag-of-words, TF-IDF ও সেন্টেন্স এমবেডিং</strong>।</p><p><strong>all-mpnet-base-v2</strong>-এর সেন্টেন্স এমবেডিং ও লজিস্টিক রিগ্রেশন সেরা হালকা মডেল: <strong>৯১.১১% accuracy ও ৯৬.৯৪% ROC-AUC</strong>, ৪১৯টি পুনরাবৃত্ত রিভিউ বাদ দিয়ে মাপা, যাতে কোনো টেস্ট রিভিউ ট্রেনিংয়ে না থাকে। ১৬-বিট কপি সম্পূর্ণ ব্রাউজার ডেমোতে চলে, এবং এমবেড করা ডেটাসেট Kaggle-এ।</p>$q$, ARRAY[$q$Compared three text representations across six classifiers on IMDB 50K (25,000 positive, 25,000 negative).$q$, $q$Removed 419 repeated reviews before an 80/20 stratified split (39,664 training, 9,917 test).$q$, $q$Chose MPNet embeddings + logistic regression (C = 10): 91.11% accuracy, 91.22% F1, 96.94% ROC-AUC.$q$, $q$Picked the far smaller logistic regression over an RBF SVM that keeps tens of thousands of support vectors.$q$, $q$Shipped a 16-bit ONNX embedding model for the browser demo (probabilities within 0.009 of full precision).$q$]::text[], ARRAY[$q$IMDB 50K-এ (২৫,০০০ ইতিবাচক, ২৫,০০০ নেতিবাচক) ছয়টি ক্লাসিফায়ারে তিনটি টেক্সট উপস্থাপনার তুলনা।$q$, $q$৮০/২০ স্তরভিত্তিক বিভাজনের (৩৯,৬৬৪ ট্রেনিং, ৯,৯১৭ টেস্ট) আগে ৪১৯টি পুনরাবৃত্ত রিভিউ বাদ।$q$, $q$MPNet এমবেডিং + লজিস্টিক রিগ্রেশন (C = ১০) নির্বাচন: ৯১.১১% accuracy, ৯১.২২% F1, ৯৬.৯৪% ROC-AUC।$q$, $q$হাজার হাজার সাপোর্ট ভেক্টর রাখা RBF SVM-এর বদলে অনেক ছোট লজিস্টিক রিগ্রেশন বেছে নেওয়া।$q$, $q$ব্রাউজার ডেমোর জন্য ১৬-বিট ONNX এমবেডিং মডেল (পূর্ণ মডেলের ০.০০৯-এর মধ্যে সম্ভাবনা)।$q$]::text[]),
  ($q$researcher$q$, $q$Shukhee$q$, $q$সুখী$q$, $q$Jun 2026 – Present$q$, $q$জুন ২০২৬ – বর্তমান$q$, ARRAY[$q$AI Assistant$q$, $q$TypeScript$q$, $q$NestJS$q$, $q$PostgreSQL$q$, $q$Prisma$q$, $q$Redis$q$, $q$BullMQ$q$, $q$Payment Gateways$q$]::text[], $q$<p><strong>Shukhee</strong> is Grameen Health Tech's all-in-one healthcare platform for Bangladesh: teleconsultation with doctors, lab tests with home sample collection, medicine delivery, emergency services and the HealthStore shop, reachable through the app, the web, a hotline and rural Shukhee Seba Kendra centres.</p><p>I build its <strong>AI patient-assistant chat</strong>, which supports patients through the whole care journey, from finding the right service to follow-up, along with the core healthcare APIs, payments and the background processing that keeps operations reliable.</p>$q$, $q$<p><strong>সুখী</strong> হলো বাংলাদেশের জন্য গ্রামীণ হেলথ টেকের সর্বাঙ্গীণ স্বাস্থ্যসেবা প্ল্যাটফর্ম: ডাক্তারের সাথে টেলিকনসালটেশন, বাড়ি থেকে নমুনা সংগ্রহসহ ল্যাব টেস্ট, ওষুধ সরবরাহ, জরুরি সেবা ও হেলথস্টোর, অ্যাপ, ওয়েব, হটলাইন ও গ্রামীণ সুখী সেবা কেন্দ্রের মাধ্যমে।</p><p>আমি এর <strong>এআই পেশেন্ট-অ্যাসিস্ট্যান্ট চ্যাট</strong> তৈরি করি, যা সঠিক সেবা খোঁজা থেকে ফলো-আপ পর্যন্ত রোগীর পুরো চিকিৎসা-যাত্রায় সহায়তা করে, সাথে মূল স্বাস্থ্যসেবা API, পেমেন্ট ও কার্যক্রম নির্ভরযোগ্য রাখা ব্যাকগ্রাউন্ড প্রসেসিং।</p>$q$, ARRAY[$q$Build the AI assistant chat that guides patients across the care journey on Shukhee.$q$, $q$Develop core healthcare APIs and supporting backend services within a NestJS architecture.$q$, $q$Implement payment APIs, HealthStore e-commerce and bulk-processing endpoints.$q$, $q$Run scheduled and asynchronous workflows with cron jobs, BullMQ and Redis for automated operations.$q$, $q$Model database relationships and business logic for reliable healthcare transactions.$q$]::text[], ARRAY[$q$সুখীতে রোগীদের পুরো চিকিৎসা-যাত্রায় পথ দেখানো এআই অ্যাসিস্ট্যান্ট চ্যাট তৈরি।$q$, $q$NestJS আর্কিটেকচারে মূল স্বাস্থ্যসেবা API ও সহায়ক ব্যাকএন্ড সার্ভিস তৈরি।$q$, $q$পেমেন্ট API, হেলথস্টোর ই-কমার্স ও বাল্ক-প্রসেসিং এন্ডপয়েন্ট বাস্তবায়ন।$q$, $q$স্বয়ংক্রিয় কার্যক্রমের জন্য cron, BullMQ ও Redis দিয়ে নির্ধারিত ও অ্যাসিঙ্ক্রোনাস ওয়ার্কফ্লো পরিচালনা।$q$, $q$নির্ভরযোগ্য স্বাস্থ্যসেবা লেনদেনের জন্য ডেটাবেস সম্পর্ক ও ব্যবসায়িক যুক্তির মডেলিং।$q$]::text[]),
  ($q$researcher$q$, $q$Radd$q$, $q$রাদ$q$, $q$Dec 2025 – Jun 2026$q$, $q$ডিসেম্বর ২০২৫ – জুন ২০২৬$q$, ARRAY[$q$LLM$q$, $q$TypeScript$q$, $q$NestJS$q$, $q$PostgreSQL$q$, $q$TypeORM$q$, $q$Redis$q$, $q$RabbitMQ$q$, $q$WhatsApp Cloud API$q$, $q$AWS$q$]::text[], $q$<p><strong>Radd</strong> is an AI-first customer-service and messaging platform for Arabic businesses on the official WhatsApp (Meta) API. Its AI service studies each client's business and writes tailored marketing and engagement messages; the core system then delivers them to large contact lists.</p><p>I built the messaging core and the <strong>event-driven bridge between the core system and the LLM service</strong>, and made million-scale delivery dependable despite frequent Meta API failures.</p>$q$, $q$<p><strong>রাদ</strong> হলো অফিসিয়াল WhatsApp (Meta) API-তে আরব ব্যবসার জন্য এআই-প্রথম গ্রাহকসেবা ও মেসেজিং প্ল্যাটফর্ম। এর এআই সার্ভিস প্রতিটি ক্লায়েন্টের ব্যবসা বিশ্লেষণ করে উপযুক্ত মার্কেটিং ও এনগেজমেন্ট বার্তা লেখে; মূল সিস্টেম সেগুলো বড় কন্ট্যাক্ট তালিকায় পৌঁছে দেয়।</p><p>আমি মেসেজিং কোর ও <strong>মূল সিস্টেম ও এলএলএম সার্ভিসের মধ্যে ইভেন্ট-ড্রিভেন সংযোগ</strong> তৈরি করেছি, এবং ঘন ঘন Meta API ব্যর্থতা সত্ত্বেও লাখো বার্তা নির্ভরযোগ্যভাবে পৌঁছানো নিশ্চিত করেছি।</p>$q$, ARRAY[$q$Built core messaging services on the official WhatsApp Cloud API for Arabic businesses.$q$, $q$Designed event-driven microservices over RabbitMQ connecting the core system with the AI service for message generation and delivery.$q$, $q$Developed AI-generated broadcast campaigns that analyse each client's business and write tailored messages.$q$, $q$Engineered a high-volume bulk pipeline delivering million-scale messages across large contact lists.$q$, $q$Stabilised delivery against Meta API failures with queue-based processing, retries and failure tracking.$q$]::text[], ARRAY[$q$আরব ব্যবসার জন্য অফিসিয়াল WhatsApp Cloud API-তে মূল মেসেজিং সার্ভিস তৈরি।$q$, $q$বার্তা তৈরি ও পৌঁছানোর জন্য মূল সিস্টেম ও এআই সার্ভিস যুক্ত RabbitMQ-ভিত্তিক ইভেন্ট-ড্রিভেন মাইক্রোসার্ভিস নকশা।$q$, $q$প্রতিটি ক্লায়েন্টের ব্যবসা বিশ্লেষণ করে উপযুক্ত বার্তা লেখা এআই-জেনারেটেড ব্রডকাস্ট ক্যাম্পেইন তৈরি।$q$, $q$বড় কন্ট্যাক্ট তালিকায় লাখো বার্তা পৌঁছানো উচ্চ-ভলিউম বাল্ক পাইপলাইন নির্মাণ।$q$, $q$কিউ-ভিত্তিক প্রসেসিং, পুনঃচেষ্টা ও ব্যর্থতা ট্র্যাকিং দিয়ে Meta API ব্যর্থতার বিপরীতে ডেলিভারি স্থিতিশীল করা।$q$]::text[]),
  ($q$researcher$q$, $q$Jamahook$q$, $q$জামাহুক – এআই মিউজিক জেনারেটর$q$, $q$May 2025 – Present$q$, $q$মে ২০২৫ – বর্তমান$q$, ARRAY[$q$Generative AI$q$, $q$Stable Audio$q$, $q$Python$q$, $q$FastAPI$q$, $q$Docker$q$]::text[], $q$<p><strong>Jamahook</strong> is an AI-assisted music-production tool that works alongside a digital audio workstation. I designed and built its <strong>solo-instrument generation service</strong>, which creates instrumental parts with Stable Audio open models.</p><p>The work covered choosing a deployment architecture that fits the platform's constraints for generative audio inference, and integrating the service into Jamahook's real-time DAW assistant.</p>$q$, $q$<p><strong>জামাহুক</strong> একটি এআই-সহায়িত মিউজিক প্রোডাকশন টুল, যা ডিজিটাল অডিও ওয়ার্কস্টেশনের পাশাপাশি কাজ করে। আমি এর <strong>সোলো-ইনস্ট্রুমেন্ট জেনারেশন সার্ভিস</strong> নকশা ও তৈরি করেছি, যা Stable Audio উন্মুক্ত মডেল দিয়ে ইনস্ট্রুমেন্টাল অংশ তৈরি করে।</p><p>কাজের মধ্যে ছিল জেনারেটিভ অডিও ইনফারেন্সের জন্য প্ল্যাটফর্মের সীমার সাথে মানানসই ডিপ্লয়মেন্ট আর্কিটেকচার বাছাই এবং জামাহুকের রিয়েল-টাইম DAW অ্যাসিস্ট্যান্টে সার্ভিসটি যুক্ত করা।</p>$q$, ARRAY[$q$Designed and developed a solo-instrument generation service on Stable Audio open models.$q$, $q$Analysed platform constraints to choose the deployment architecture for generative audio inference.$q$, $q$Exposed generation through a FastAPI service packaged with Docker.$q$, $q$Integrated the service into Jamahook's real-time DAW assistant.$q$]::text[], ARRAY[$q$Stable Audio উন্মুক্ত মডেলে সোলো-ইনস্ট্রুমেন্ট জেনারেশন সার্ভিস নকশা ও তৈরি।$q$, $q$জেনারেটিভ অডিও ইনফারেন্সের ডিপ্লয়মেন্ট আর্কিটেকচার বাছাইয়ে প্ল্যাটফর্মের সীমা বিশ্লেষণ।$q$, $q$Docker-এ প্যাকেজ করা FastAPI সার্ভিসের মাধ্যমে জেনারেশন উন্মুক্ত করা।$q$, $q$জামাহুকের রিয়েল-টাইম DAW অ্যাসিস্ট্যান্টে সার্ভিস যুক্ত করা।$q$]::text[]),
  ($q$researcher$q$, $q$Chat Brokers$q$, $q$চ্যাট ব্রোকার্স$q$, $q$Mar 2025 – May 2025$q$, $q$মার্চ ২০২৫ – মে ২০২৫$q$, ARRAY[$q$LLM$q$, $q$RAG$q$, $q$MCP$q$, $q$LangChain$q$, $q$Python$q$, $q$FastAPI$q$, $q$PostgreSQL$q$]::text[], $q$<p><strong>Chat Brokers</strong> is an LLM-powered assistant that answers questions about brokers in natural, context-aware conversation and helps users compare them. Broker profiles come in many shapes, so the system first ingests and structures them into a consistent data model.</p><p>On top of that data I designed a <strong>retrieval-augmented generation (RAG) and Model Context Protocol (MCP) toolset</strong> that lets the model look up facts, compare brokers and recommend options, and I owned the end-to-end architecture.</p>$q$, $q$<p><strong>চ্যাট ব্রোকার্স</strong> একটি এলএলএম-চালিত অ্যাসিস্ট্যান্ট, যা স্বাভাবিক, প্রেক্ষাপট-সচেতন কথোপকথনে ব্রোকার সম্পর্কে প্রশ্নের উত্তর দেয় ও তুলনায় সাহায্য করে। ব্রোকার প্রোফাইল নানা রূপে আসে, তাই সিস্টেম প্রথমে সেগুলো সংগ্রহ করে একটি সামঞ্জস্যপূর্ণ ডেটা মডেলে সাজায়।</p><p>সেই ডেটার ওপর আমি একটি <strong>রিট্রিভাল-অগমেন্টেড জেনারেশন (RAG) ও মডেল কনটেক্সট প্রটোকল (MCP) টুলসেট</strong> নকশা করেছি, যা মডেলকে তথ্য খুঁজতে, ব্রোকার তুলনা ও সুপারিশ করতে দেয়, এবং পুরো আর্কিটেকচারের দায়িত্ব নিয়েছি।</p>$q$, ARRAY[$q$Built the ingestion and structuring pipeline that turns diverse broker profiles into one data model.$q$, $q$Designed RAG retrieval and MCP tools for fact lookup, broker comparison and recommendations.$q$, $q$Delivered dynamic, context-aware conversations with an LLM through LangChain.$q$, $q$Owned the end-to-end architecture and data model, served through FastAPI on PostgreSQL.$q$]::text[], ARRAY[$q$বিভিন্ন ব্রোকার প্রোফাইলকে একটি ডেটা মডেলে আনা সংগ্রহ ও সাজানোর পাইপলাইন তৈরি।$q$, $q$তথ্য খোঁজা, ব্রোকার তুলনা ও সুপারিশের জন্য RAG রিট্রিভাল ও MCP টুল নকশা।$q$, $q$LangChain-এর মাধ্যমে এলএলএম দিয়ে গতিশীল, প্রেক্ষাপট-সচেতন কথোপকথন।$q$, $q$PostgreSQL-এ FastAPI দিয়ে পরিবেশিত পুরো আর্কিটেকচার ও ডেটা মডেলের দায়িত্ব।$q$]::text[]),
  ($q$researcher$q$, $q$Cannella$q$, $q$ক্যানেলা রিক্রুটমেন্ট সার্ভিস (এআই)$q$, $q$Feb 2025 – Apr 2025$q$, $q$ফেব্রুয়ারি ২০২৫ – এপ্রিল ২০২৫$q$, ARRAY[$q$Machine Learning$q$, $q$NLP$q$, $q$Python$q$, $q$scikit-learn$q$, $q$PostgreSQL$q$]::text[], $q$<p><strong>Cannella</strong> is an AI recruitment service that matches candidates to roles. It reads job requirements and applicants' CVs, represents both as comparable text features, and ranks candidates for each job.</p><p>I developed the matching and ranking models and tuned them for both <strong>accuracy and speed</strong>, so recruiters see the most relevant applicants first.</p>$q$, $q$<p><strong>ক্যানেলা</strong> একটি এআই নিয়োগ সেবা, যা প্রার্থীদের পদের সাথে মেলায়। এটি চাকরির প্রয়োজনীয়তা ও আবেদনকারীর সিভি পড়ে, দুটিকে তুলনীয় টেক্সট ফিচারে উপস্থাপন করে, এবং প্রতিটি চাকরির জন্য প্রার্থীদের র‍্যাঙ্ক করে।</p><p>আমি ম্যাচিং ও র‍্যাঙ্কিং মডেল তৈরি করে <strong>নির্ভুলতা ও গতি</strong> দুটোর জন্যই টিউন করেছি, যাতে নিয়োগকর্তারা সবচেয়ে প্রাসঙ্গিক আবেদনকারীদের আগে দেখেন।</p>$q$, ARRAY[$q$Developed NLP models that analyse job requirements and applicant CVs.$q$, $q$Implemented machine-learning ranking of candidates for each job.$q$, $q$Optimised the pipeline for accuracy and response time.$q$, $q$Stored jobs, candidates and scores in PostgreSQL for the recruitment workflow.$q$]::text[], ARRAY[$q$চাকরির প্রয়োজনীয়তা ও আবেদনকারীর সিভি বিশ্লেষণে এনএলপি মডেল তৈরি।$q$, $q$প্রতিটি চাকরির জন্য প্রার্থীদের মেশিন লার্নিং র‍্যাঙ্কিং বাস্তবায়ন।$q$, $q$নির্ভুলতা ও সাড়া-সময়ের জন্য পাইপলাইন অপ্টিমাইজ।$q$, $q$নিয়োগ ওয়ার্কফ্লোর জন্য PostgreSQL-এ চাকরি, প্রার্থী ও স্কোর সংরক্ষণ।$q$]::text[]),
  ($q$researcher$q$, $q$Query AI$q$, $q$কোয়েরি এআই$q$, $q$Oct 2024 – Jan 2025$q$, $q$অক্টোবর ২০২৪ – জানুয়ারি ২০২৫$q$, ARRAY[$q$Python$q$, $q$FastAPI$q$, $q$NLP$q$, $q$SpaCy$q$, $q$pgVector$q$, $q$SQLAlchemy$q$, $q$PostgreSQL$q$]::text[], $q$<p><strong>Query AI</strong> turns a plain-language question into a working SQL query and runs it, so people can get answers from a database without writing SQL. It bridges what the user means and what the data holds.</p><p>The system parses the question with <strong>SpaCy</strong>, finds the relevant tables and values through <strong>pgVector semantic search</strong> over the schema and data, generates the SQL and executes it against PostgreSQL through a FastAPI backend.</p>$q$, $q$<p><strong>কোয়েরি এআই</strong> সাধারণ ভাষার প্রশ্নকে কার্যকর SQL কোয়েরিতে রূপান্তর করে চালায়, যাতে SQL না লিখেই ডেটাবেস থেকে উত্তর পাওয়া যায়। এটি ব্যবহারকারীর উদ্দেশ্য ও ডেটার মধ্যে সেতুবন্ধন।</p><p>সিস্টেমটি <strong>SpaCy</strong> দিয়ে প্রশ্ন বিশ্লেষণ করে, স্কিমা ও ডেটার ওপর <strong>pgVector সিমান্টিক সার্চ</strong> দিয়ে প্রাসঙ্গিক টেবিল ও মান খুঁজে, SQL তৈরি করে এবং FastAPI ব্যাকএন্ডের মাধ্যমে PostgreSQL-এ চালায়।</p>$q$, ARRAY[$q$Developed an NLP-based natural-language-to-SQL generator with FastAPI.$q$, $q$Used pgVector for semantic vector search over schema and data, with PostgreSQL for structured storage.$q$, $q$Parsed user intent with SpaCy to map questions onto tables, columns and filters.$q$, $q$Designed the full database and the query-execution flow, from question to result.$q$]::text[], ARRAY[$q$FastAPI দিয়ে এনএলপি-ভিত্তিক প্রাকৃতিক ভাষা থেকে SQL জেনারেটর তৈরি।$q$, $q$স্কিমা ও ডেটার ওপর সিমান্টিক ভেক্টর সার্চে pgVector, কাঠামোগত সংরক্ষণে PostgreSQL।$q$, $q$প্রশ্নকে টেবিল, কলাম ও ফিল্টারে মেলাতে SpaCy দিয়ে ব্যবহারকারীর উদ্দেশ্য বিশ্লেষণ।$q$, $q$প্রশ্ন থেকে ফলাফল পর্যন্ত পুরো ডেটাবেস ও কোয়েরি-এক্সিকিউশন প্রবাহ নকশা।$q$]::text[]),
  ($q$researcher$q$, $q$Probashkormi$q$, $q$প্রবাসকর্মী$q$, $q$Aug 2023 – Aug 2025$q$, $q$আগস্ট ২০২৩ – আগস্ট ২০২৫$q$, ARRAY[$q$AI Job Matching$q$, $q$TypeScript$q$, $q$NestJS$q$, $q$MongoDB$q$, $q$Prisma$q$, $q$AdminJS$q$, $q$AWS S3$q$]::text[], $q$<p><strong>Probashkormi</strong> is a recruitment platform that connects Bangladeshi job seekers with verified overseas employers. Its <strong>AI job matching</strong> suggests suitable jobs for each candidate, helping workers find safe, legitimate opportunities abroad.</p><p>I designed the system and database schema from the client's requirements and built the full-stack platform, including file storage and the admin interface.</p>$q$, $q$<p><strong>প্রবাসকর্মী</strong> একটি নিয়োগ প্ল্যাটফর্ম, যা বাংলাদেশি চাকরিপ্রার্থীদের যাচাইকৃত বিদেশি নিয়োগকর্তার সাথে যুক্ত করে। এর <strong>এআই জব ম্যাচিং</strong> প্রতিটি প্রার্থীর জন্য উপযুক্ত চাকরি সুপারিশ করে, যাতে কর্মীরা বিদেশে নিরাপদ, বৈধ সুযোগ পান।</p><p>ক্লায়েন্টের প্রয়োজন অনুযায়ী আমি সিস্টেম ও ডেটাবেস স্কিমা নকশা করে ফাইল সংরক্ষণ ও অ্যাডমিন ইন্টারফেসসহ পূর্ণাঙ্গ প্ল্যাটফর্ম তৈরি করেছি।</p>$q$, ARRAY[$q$Integrated AI job matching that suggests suitable overseas jobs to each candidate.$q$, $q$Designed the system and database schema from client requirements to support the core modules.$q$, $q$Built the full-stack platform with NestJS, MongoDB and Prisma.$q$, $q$Integrated AWS S3 for documents and AdminJS for administration and resource management.$q$]::text[], ARRAY[$q$প্রতিটি প্রার্থীকে উপযুক্ত বিদেশি চাকরি সুপারিশকারী এআই জব ম্যাচিং যুক্ত করা।$q$, $q$মূল মডিউলের জন্য ক্লায়েন্টের প্রয়োজন অনুযায়ী সিস্টেম ও ডেটাবেস স্কিমা নকশা।$q$, $q$NestJS, MongoDB ও Prisma দিয়ে পূর্ণাঙ্গ প্ল্যাটফর্ম তৈরি।$q$, $q$ডকুমেন্টের জন্য AWS S3 ও প্রশাসন ও রিসোর্স ব্যবস্থাপনার জন্য AdminJS যুক্ত করা।$q$]::text[]),
  ($q$researcher$q$, $q$SoftCollab$q$, $q$সফটকোলাব$q$, $q$Apr 2023 – Aug 2025$q$, $q$এপ্রিল ২০২৩ – আগস্ট ২০২৫$q$, ARRAY[$q$Generative AI$q$, $q$ExpressJS$q$, $q$Socket.IO$q$, $q$FFmpeg$q$, $q$ImageMagick$q$, $q$MySQL$q$, $q$AWS S3$q$]::text[], $q$<p><strong>SoftCollab</strong> is a music-collaboration platform where producers and musicians create together. It offers <strong>AI-based music generation</strong> alongside real-time collaboration and media handling.</p><p>I upgraded the platform's backend, built the audio and image processing pipelines and the real-time collaboration layer, and managed media storage in the cloud.</p>$q$, $q$<p><strong>সফটকোলাব</strong> একটি মিউজিক-সহযোগিতা প্ল্যাটফর্ম, যেখানে প্রযোজক ও সংগীতশিল্পীরা একসাথে তৈরি করেন। এতে রিয়েল-টাইম সহযোগিতা ও মিডিয়া ব্যবস্থাপনার পাশাপাশি <strong>এআই-ভিত্তিক মিউজিক জেনারেশন</strong> রয়েছে।</p><p>আমি প্ল্যাটফর্মের ব্যাকএন্ড উন্নত করেছি, অডিও ও ছবি প্রসেসিং পাইপলাইন ও রিয়েল-টাইম সহযোগিতা স্তর তৈরি করেছি, এবং ক্লাউডে মিডিয়া সংরক্ষণ পরিচালনা করেছি।</p>$q$, ARRAY[$q$Supported AI-based music generation for producers and musicians on the platform.$q$, $q$Upgraded the backend with ExpressJS and MySQL.$q$, $q$Implemented audio and image processing with FFmpeg and ImageMagick.$q$, $q$Built real-time collaboration over Socket.IO and handled file storage on AWS S3.$q$]::text[], ARRAY[$q$প্ল্যাটফর্মে প্রযোজক ও সংগীতশিল্পীদের জন্য এআই-ভিত্তিক মিউজিক জেনারেশনে সহায়তা।$q$, $q$ExpressJS ও MySQL দিয়ে ব্যাকএন্ড উন্নয়ন।$q$, $q$FFmpeg ও ImageMagick দিয়ে অডিও ও ছবি প্রসেসিং বাস্তবায়ন।$q$, $q$Socket.IO-তে রিয়েল-টাইম সহযোগিতা তৈরি ও AWS S3-এ ফাইল সংরক্ষণ।$q$]::text[]),
  ($q$researcher$q$, $q$Roboket$q$, $q$রোবোকেট – মার্কেটিং অটোমেশন সিস্টেম$q$, $q$Feb 2021 – Mar 2023$q$, $q$ফেব্রুয়ারি ২০২১ – মার্চ ২০২৩$q$, ARRAY[$q$AI Decision Support$q$, $q$JavaScript$q$, $q$ReactJS$q$, $q$Python$q$, $q$FastAPI$q$, $q$Mautic API$q$]::text[], $q$<p><strong>Roboket</strong> is a marketing-automation and lead-generation system. It uses <strong>AI-driven decision making from client activity</strong> to choose who to target and when, and connects to Mautic and Facebook for campaigns and lead capture.</p><p>I led its ReactJS micro-frontends, with dynamic form validation and responsive design, and supported the backend team with FastAPI integration and the lead capture and processing flows.</p>$q$, $q$<p><strong>রোবোকেট</strong> একটি মার্কেটিং-অটোমেশন ও লিড-জেনারেশন সিস্টেম। এটি <strong>গ্রাহকের কার্যকলাপ থেকে এআই-চালিত সিদ্ধান্তে</strong> কাকে কখন লক্ষ্য করা হবে তা বেছে নেয়, এবং ক্যাম্পেইন ও লিড সংগ্রহে Mautic ও Facebook-এর সাথে যুক্ত।</p><p>আমি এর ReactJS মাইক্রো-ফ্রন্টএন্ডের নেতৃত্ব দিয়েছি, গতিশীল ফর্ম যাচাই ও রেসপন্সিভ নকশাসহ, এবং FastAPI ইন্টিগ্রেশন ও লিড সংগ্রহ ও প্রসেসিং প্রবাহে ব্যাকএন্ড দলকে সহায়তা করেছি।</p>$q$, ARRAY[$q$Supported AI-driven targeting that chooses marketing audiences from client activity.$q$, $q$Integrated Mautic and Facebook APIs for campaigns and lead generation.$q$, $q$Led ReactJS micro-frontend development with dynamic form validation and responsive design.$q$, $q$Supported the backend with FastAPI integration and designed lead capture and processing flows.$q$]::text[], ARRAY[$q$গ্রাহকের কার্যকলাপ থেকে মার্কেটিং দর্শক বেছে নেওয়া এআই-চালিত টার্গেটিংয়ে সহায়তা।$q$, $q$ক্যাম্পেইন ও লিড জেনারেশনের জন্য Mautic ও Facebook API ইন্টিগ্রেশন।$q$, $q$গতিশীল ফর্ম যাচাই ও রেসপন্সিভ নকশাসহ ReactJS মাইক্রো-ফ্রন্টএন্ড ডেভেলপমেন্টের নেতৃত্ব।$q$, $q$FastAPI ইন্টিগ্রেশনে ব্যাকএন্ডে সহায়তা ও লিড সংগ্রহ ও প্রসেসিং প্রবাহ নকশা।$q$]::text[]),
  ($q$researcher$q$, $q$Document RAG Pipeline$q$, $q$ডকুমেন্ট RAG পাইপলাইন$q$, $q$Independent research · 2025$q$, $q$স্বাধীন গবেষণা · ২০২৫$q$, ARRAY[$q$LangChain$q$, $q$FAISS$q$, $q$DeepSeek-LLM$q$, $q$Embeddings$q$, $q$Python$q$]::text[], $q$<p>An independent study of <strong>retrieval-augmented generation (RAG)</strong>: answering questions about long PDF documents with an LLM that cites what it retrieved instead of guessing.</p><p>The pipeline loads PDFs, splits them into overlapping chunks, embeds them, indexes them in <strong>FAISS</strong> and, for each question, retrieves the most relevant chunks and passes them to <strong>DeepSeek-LLM</strong> through LangChain. I published a step-by-step technical write-up on Medium.</p>$q$, $q$<p><strong>রিট্রিভাল-অগমেন্টেড জেনারেশন (RAG)</strong> নিয়ে একটি স্বাধীন গবেষণা: অনুমানের বদলে খুঁজে পাওয়া অংশের ওপর ভিত্তি করে এলএলএম দিয়ে দীর্ঘ PDF ডকুমেন্ট সম্পর্কে প্রশ্নের উত্তর।</p><p>পাইপলাইনটি PDF লোড করে, ওভারল্যাপিং অংশে ভাগ করে, এমবেড করে, <strong>FAISS</strong>-এ ইনডেক্স করে এবং প্রতিটি প্রশ্নে সবচেয়ে প্রাসঙ্গিক অংশ খুঁজে LangChain-এর মাধ্যমে <strong>DeepSeek-LLM</strong>-এ পাঠায়। Medium-এ ধাপে ধাপে প্রযুক্তিগত লেখা প্রকাশ করেছি।</p>$q$, ARRAY[$q$Built PDF ingestion and chunking with overlap to keep context across chunk boundaries.$q$, $q$Embedded the chunks and indexed them in FAISS for fast similarity search.$q$, $q$Connected retrieval to DeepSeek-LLM through LangChain to answer questions from the retrieved text.$q$, $q$Published a step-by-step technical write-up on Medium.$q$]::text[], ARRAY[$q$অংশের সীমানায় প্রেক্ষাপট রাখতে ওভারল্যাপসহ PDF সংগ্রহ ও খণ্ডকরণ তৈরি।$q$, $q$দ্রুত সাদৃশ্য-অনুসন্ধানের জন্য অংশগুলো এমবেড করে FAISS-এ ইনডেক্স।$q$, $q$খুঁজে পাওয়া টেক্সট থেকে উত্তর দিতে LangChain-এর মাধ্যমে রিট্রিভালকে DeepSeek-LLM-এর সাথে যুক্ত করা।$q$, $q$Medium-এ ধাপে ধাপে প্রযুক্তিগত লেখা প্রকাশ।$q$]::text[]),
  ($q$researcher$q$, $q$MCP Server with Gemini$q$, $q$Gemini 2.0 Flash দিয়ে MCP সার্ভার$q$, $q$Independent research · 2025$q$, $q$স্বাধীন গবেষণা · ২০২৫$q$, ARRAY[$q$MCP$q$, $q$Gemini 2.0 Flash$q$, $q$LLM Tooling$q$, $q$Agentic AI$q$, $q$Python$q$]::text[], $q$<p>An independent exploration of the <strong>Model Context Protocol (MCP)</strong>, the open standard that lets language models call tools and share structured context. Most examples pair MCP with one specific model; this project built an MCP setup around <strong>Gemini 2.0 Flash</strong> instead.</p><p>The result keeps persistent, structured context across LLM tools, a small step toward the agentic systems I want to study, where several agents plan, act and coordinate. I published a technical write-up on Medium.</p>$q$, $q$<p><strong>মডেল কনটেক্সট প্রটোকল (MCP)</strong> নিয়ে একটি স্বাধীন অনুসন্ধান — এমন উন্মুক্ত মানদণ্ড, যা ভাষা মডেলকে টুল ব্যবহার ও কাঠামোগত প্রেক্ষাপট ভাগ করতে দেয়। বেশিরভাগ উদাহরণে MCP একটি নির্দিষ্ট মডেলের সাথে ব্যবহৃত হয়; এই প্রকল্প বরং <strong>Gemini 2.0 Flash</strong> ঘিরে MCP সেটআপ তৈরি করেছে।</p><p>ফলাফল এলএলএম টুলগুলোর মধ্যে স্থায়ী, কাঠামোগত প্রেক্ষাপট রাখে — আমি যে এজেন্টিক সিস্টেম নিয়ে গবেষণা করতে চাই, যেখানে একাধিক এজেন্ট পরিকল্পনা, কাজ ও সমন্বয় করে, তার দিকে একটি ছোট পদক্ষেপ। Medium-এ প্রযুক্তিগত লেখা প্রকাশ করেছি।</p>$q$, ARRAY[$q$Built an MCP server and client around Gemini 2.0 Flash.$q$, $q$Kept persistent, structured context across LLM tools through the protocol.$q$, $q$Compared the setup with the more common single-vendor MCP examples.$q$, $q$Published a technical write-up on Medium.$q$]::text[], ARRAY[$q$Gemini 2.0 Flash ঘিরে MCP সার্ভার ও ক্লায়েন্ট তৈরি।$q$, $q$প্রটোকলের মাধ্যমে এলএলএম টুলগুলোর মধ্যে স্থায়ী, কাঠামোগত প্রেক্ষাপট রাখা।$q$, $q$প্রচলিত একক-প্রতিষ্ঠানের MCP উদাহরণের সাথে সেটআপের তুলনা।$q$, $q$Medium-এ প্রযুক্তিগত লেখা প্রকাশ।$q$]::text[]),
  ($q$researcher$q$, $q$Singistic$q$, $q$সিঙ্গিস্টিক$q$, $q$Mar 2023 – Aug 2023$q$, $q$মার্চ ২০২৩ – আগস্ট ২০২৩$q$, ARRAY[$q$Spleeter$q$, $q$Deep Learning$q$, $q$FFmpeg$q$, $q$ImageMagick$q$, $q$NestJS$q$, $q$DynamoDB$q$, $q$AWS S3$q$]::text[], $q$<p><strong>Singistic</strong> is an online karaoke app for the web, Android and iOS. To turn any song into a karaoke track, it uses <strong>Spleeter</strong>, a deep-learning source-separation model, to split the vocals from the music.</p><p>I worked on the backend: the separation and audio processing pipeline with FFmpeg, media handling with ImageMagick, and storage on AWS S3 and DynamoDB behind a NestJS API.</p>$q$, $q$<p><strong>সিঙ্গিস্টিক</strong> ওয়েব, অ্যান্ড্রয়েড ও iOS-এর জন্য একটি অনলাইন কারাওকে অ্যাপ। যেকোনো গানকে কারাওকে ট্র্যাকে রূপ দিতে এটি <strong>Spleeter</strong> — একটি ডিপ লার্নিং সোর্স-সেপারেশন মডেল — দিয়ে গান থেকে কণ্ঠ আলাদা করে।</p><p>আমি ব্যাকএন্ডে কাজ করেছি: FFmpeg দিয়ে সেপারেশন ও অডিও প্রসেসিং পাইপলাইন, ImageMagick দিয়ে মিডিয়া ব্যবস্থাপনা, এবং NestJS API-র পেছনে AWS S3 ও DynamoDB-তে সংরক্ষণ।</p>$q$, ARRAY[$q$Used Spleeter deep-learning source separation to split vocals from music.$q$, $q$Built the audio processing pipeline with FFmpeg and media handling with ImageMagick.$q$, $q$Developed the NestJS API with storage on AWS S3 and DynamoDB.$q$, $q$Served the web, Android and iOS apps from one backend.$q$]::text[], ARRAY[$q$গান থেকে কণ্ঠ আলাদা করতে Spleeter ডিপ লার্নিং সোর্স সেপারেশন ব্যবহার।$q$, $q$FFmpeg দিয়ে অডিও প্রসেসিং পাইপলাইন ও ImageMagick দিয়ে মিডিয়া ব্যবস্থাপনা তৈরি।$q$, $q$AWS S3 ও DynamoDB-তে সংরক্ষণসহ NestJS API তৈরি।$q$, $q$একটি ব্যাকএন্ড থেকে ওয়েব, অ্যান্ড্রয়েড ও iOS অ্যাপ পরিবেশন।$q$]::text[])
) AS v(scope, match, title_bn, duration_en, duration_bn, tech, desc_en, desc_bn, bul_en, bul_bn)
WHERE p.user_id = '88b3efb5-8c58-486e-a3f7-751cc4b23e60'
  AND p.title_en ILIKE v.match || '%'
  AND p.updated_at = p.created_at
  AND CASE v.scope
        WHEN 'all' THEN p.versions = '{}'
        ELSE EXISTS (SELECT 1 FROM pf_versions r
                     WHERE r.user_id = p.user_id AND r.slug = 'researcher' AND r.id = ANY(p.versions))
      END;

COMMIT;
